import Component from 'flarum/common/Component';
import app from 'flarum/admin/app';
import { joinColor, splitColor } from '../utils/color';
const t = (key, params = {}) => app.translator.trans(`walsgit-custom-heroes.admin.overlay.${key}`, params, true);

/** A color with its opacity, as `#rrggbbaa`. */
export default class AlphaColorInput extends Component {
  view() {
    const {
      value,
      onchange,
      label,
      legends
    } = this.attrs;
    const {
      rgb,
      opacity
    } = splitColor(value);
    const color = m("input", {
      type: "color",
      className: "wch-AlphaColor-color",
      value: rgb,
      "aria-label": label,
      oninput: e => onchange(joinColor(e.target.value, opacity))
    });
    const alpha = m("div", {
      className: "wch-AlphaColor-alpha"
    }, m("input", {
      type: "range",
      className: "wch-AlphaColor-opacity",
      min: "0",
      max: "100",
      value: opacity,
      "aria-label": t('opacity_label', {
        label
      }),
      oninput: e => onchange(joinColor(rgb, Number(e.target.value)))
    }), m("span", {
      className: "wch-AlphaColor-value"
    }, opacity, "%"));
    return legends ? m("div", {
      className: "wch-AlphaColor"
    }, legend(t('legend_color'), color), legend(t('legend_opacity'), alpha)) : m("div", {
      className: "wch-AlphaColor"
    }, color, alpha);
  }
}

/** A small caption above a control, saying what it sets. */
export function legend(text, control) {
  return m("div", {
    className: "wch-Legend"
  }, m("span", {
    className: "wch-Legend-text",
    "aria-hidden": "true"
  }, text), control);
}
flarum.reg.add('walsgit-custom-heroes', 'admin/components/AlphaColorInput', AlphaColorInput);